package lk.gov.health.govcare.pdf;
import lk.gov.health.govcare.security.*;import org.springframework.http.*;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/pdf")public class PdfReportController{private final PdfReportService s;private final CurrentUser c;public PdfReportController(PdfReportService s,CurrentUser c){this.s=s;this.c=c;}@GetMapping("/{kind}/{id}")@PreAuthorize("hasAuthority('REPORT_DOWNLOAD')")public ResponseEntity<byte[]>get(@PathVariable String kind,@PathVariable String id){PdfReportService.Report r=s.generate(c.get(),kind,id);return ResponseEntity.ok().contentType(MediaType.APPLICATION_PDF).header(HttpHeaders.CONTENT_DISPOSITION,ContentDisposition.attachment().filename(r.filename()).build().toString()).body(r.bytes());}}
